import { readdir, readFile } from "node:fs/promises";
import path from "node:path";

const root = process.cwd();
const modules = ["ji-ai-api", "ji-agent-api", "ji-session-api", "ji-error-catalog"];
const baseline = await readFile(path.join(root, "docs/java-rewrite/api-baseline/0.1.0.md"), "utf8");
for (const module of modules) {
  if (!baseline.includes(`\`${module}\``)) throw new Error(`API baseline does not list ${module}`);
}
for (const relative of [
  "ji-java/core/ji-ai-api/src/main/java",
  "ji-java/core/ji-agent-api/src/main/java",
  "ji-java/core/ji-session-api/src/main/java",
]) {
  const declarations = [];
  for (const file of await javaFiles(path.join(root, relative))) {
    const source = await readFile(file, "utf8");
    if (/public\s+(?:sealed\s+)?(?:final\s+)?(?:class|interface|record|enum)\s+/.test(source)) {
      declarations.push(path.basename(file, ".java"));
    }
  }
  if (declarations.length === 0) throw new Error(`no public API declarations found in ${relative}`);
}
process.stdout.write("Stage 1 public API baseline verified\n");

async function javaFiles(directory) {
  const result = [];
  for (const entry of await readdir(directory, { withFileTypes: true })) {
    const child = path.join(directory, entry.name);
    if (entry.isDirectory()) result.push(...await javaFiles(child));
    else if (entry.name.endsWith(".java")) result.push(child);
  }
  return result;
}

