import { execFileSync } from "node:child_process";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import process from "node:process";

const root = process.cwd();
const baselinePath = path.join(root, "docs", "java-rewrite", "api-baseline", "0.1.0-signatures.json");
const baseline = await readFile(baselinePath, "utf8");
const temp = await mkdtemp(path.join(os.tmpdir(), "ji-api-baseline-"));
try {
  const generated = path.join(temp, "0.1.0-signatures.json");
  execFileSync(process.execPath, [path.join(root, "scripts", "generate-api-baseline.mjs")], {
    cwd: root,
    stdio: "inherit",
    env: { ...process.env, JI_API_BASELINE_OUTPUT: generated },
  });
  const actual = await readFile(generated, "utf8");
  if (actual !== baseline) {
    throw new Error("Stage 1 public API signatures differ from 0.1.0 baseline; regenerate and review the API diff explicitly");
  }
  process.stdout.write("Stage 1 public API signature baseline verified\n");
} finally {
  await rm(temp, { recursive: true, force: true });
}
